class LogSettings:
    _shared_state: dict[str, object] = {}

    def __init__(self, level: int = 1) -> None:
        self.__dict__ = self._shared_state      # all instances share
        self.level = level

a = LogSettings(1)
b = LogSettings()                               # separate identity
b.level = 3
assert a.level == 3                             # same state

